const req = createRequire(path.join(genPkgDir, "package.json"))
const pkg = req("./package.json")
const entry = pkg.exports?.["."]?.import?.default ?? pkg.module ?? pkg.main
const mod = await import(pathToFileURL(path.join(genPkgDir, entry)).href)

const config = await mod.getConfig(
  {
    routesDirectory: path.join(appRoot, "src/routes"),
    generatedRouteTree: path.join(appRoot, "src/routeTree.gen.ts"),
    target: "react",
  },
  appRoot,
)
const generator = new mod.Generator({ config, root: appRoot, fs: await import("node:fs/promises") })
await generator.run()
console.log("route tree regenerated")

